const rawRows = $input.first().json.rows ?? [];

function excelDateToISO(value) {
  if (value === null || value === undefined || value === "") {
    return null;
  }

  if (typeof value === "number") {
    const baseDate = new Date(Date.UTC(1899, 11, 30));
    const date = new Date(baseDate.getTime() + value * 86400000);
    return date.toISOString().slice(0, 10);
  }

  const date = new Date(value);

  if (!Number.isNaN(date.getTime())) {
    return date.toISOString().slice(0, 10);
  }

  return String(value);
}

function toAmount(value) {
  if (typeof value === "number") {
    return value;
  }

  const cleaned = String(value ?? "")
    .replace(/[^\d.-]/g, "");

  const amount = Number(cleaned);

  return Number.isFinite(amount) ? amount : 0;
}

const workingPaper = rawRows
  .map((row, index) => {
    const description = row["__EMPTY_1"];
    const amount = toAmount(row["__EMPTY_2"]);

    return {
      row,
      index,
      description,
      amount
    };
  })
  .filter(item => {
    return item.description &&
      String(item.description).toLowerCase() !== "description" &&
      item.amount > 0;
  })
  .map((item, index) => {
    const row = item.row;

    return {
      wpRowId: index + 1,
      sourceRowIndex: item.index,
      advanceDate: excelDateToISO(
        row["PT. SETIAWAN DWI TUNGGAL"]
      ),
      voucherNo: String(row["__EMPTY"] ?? "").trim(),
      description: String(item.description).trim(),
      amount: item.amount,

      realizationDate: null,
      realizationVouchers: [],
      realizationAmount: 0,
      balance: item.amount,
      status: "UNSETTLED"
    };
  });

return [
  {
    json: {
      source: "working_paper_normalized",
      rowCount: workingPaper.length,
      workingPaper
    }
  }
];

const rawRows = $input.first().json.rows ?? [];

function getValue(row, aliases) {
  const entry = Object.entries(row).find(([key]) => {
    const normalizedKey = key
      .replace(/\s+/g, " ")
      .trim()
      .toUpperCase();

    return aliases.includes(normalizedKey);
  });

  return entry ? entry[1] : null;
}

function excelDateToISO(value) {
  if (value === null || value === undefined || value === "") {
    return null;
  }

  if (typeof value === "number") {
    const baseDate = new Date(Date.UTC(1899, 11, 30));
    const date = new Date(baseDate.getTime() + value * 86400000);
    return date.toISOString().slice(0, 10);
  }

  const date = new Date(value);

  if (!Number.isNaN(date.getTime())) {
    return date.toISOString().slice(0, 10);
  }

  return String(value);
}

function toAmount(value) {
  if (typeof value === "number") {
    return value;
  }

  const cleaned = String(value ?? "")
    .replace(/[^\d.-]/g, "");

  const amount = Number(cleaned);

  return Number.isFinite(amount) ? amount : 0;
}

const glCredits = rawRows
  .map((row, index) => {
    const credit = toAmount(
      getValue(row, ["KREDIT-IDR", "KREDIT IDR", "KREDIT"])
    );

    return {
      row,
      index,
      date: getValue(row, ["TANGGAL", "DATE"]),
      journalNo: getValue(row, ["NO JURNAL", "JOURNAL NO"]),
      description: getValue(row, ["DESKRIPSI", "DESCRIPTION"]),
      debit: toAmount(
        getValue(row, ["DEBET-IDR", "DEBET IDR", "DEBET", "DEBIT"])
      ),
      credit
    };
  })
  .filter(item => {
    return item.credit > 0;
  })
  .map((item, index) => {
    return {
      glRowId: index + 1,
      sourceRowIndex: item.index,
      date: excelDateToISO(item.date),
      journalNo: String(item.journalNo ?? "").trim(),
      description: String(item.description ?? "").trim(),
      debit: item.debit,
      credit: item.credit
    };
  });

return [
