const input = $input.first().json;

const workingPaper = input.workingPaper ?? [];
const glCredits = input.glCredits ?? [];

if (!workingPaper.length) {
  throw new Error("Working Paper kosong.");
}

if (!glCredits.length) {
  throw new Error("GL Credits kosong.");
}

const STOP_WORDS = new Set([
  "THE",
  "DI",
  "DAN",
  "DARI",
  "KE",
  "UNTUK",
  "PADA",
  "TAHUN",
  "BULAN",
  "PERIODE",
  "TGL",
  "UM",
  "ADVANCE",
  "ADVANCES",
  "PEMBAYARAN",
  "PELUNASAN",
  "PENGEMBALIAN",
  "KELEBIHAN",
  "DANA",
  "TRANSFER",
  "PENERIMAAN",
  "TAGIHAN"
]);

function cleanText(value) {
  return String(value ?? "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toUpperCase()
    .replace(/[^A-Z0-9/]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function tokens(value) {
  return cleanText(value)
    .replace(/\//g, " ")
    .split(" ")
    .filter(token => {
      return token &&
        token.length >= 2 &&
        !STOP_WORDS.has(token);
    });
}

function extractReferences(value) {
  const text = String(value ?? "").toUpperCase();

  return text.match(
    /\b[A-Z0-9]+\/(?:PO|WO)\/\d{8}\b/g
  ) ?? [];
}

function similarityScore(target, candidate) {
  const targetTokens = [...new Set(tokens(target))];
  const candidateTokens = new Set(tokens(candidate));

  const matchedTokens = targetTokens.filter(token => {
    return candidateTokens.has(token);
  });

  const score = targetTokens.length
    ? matchedTokens.length / targetTokens.length
    : 0;

  return {
    score,
    matchedTokens
  };
}

function phraseRule(target, candidate) {
  const targetText = cleanText(target);
  const candidateText = cleanText(candidate);

  // Styling Apartment 2 Bedroom
  if (
    targetText.includes("STYLING") &&
    targetText.includes("1132")
  ) {
    return (
      candidateText.includes("STYLING") &&
      candidateText.includes("1132")
    );
  }

  // Styling Apartment 1127 Studio
  if (
    targetText.includes("STYLING") &&
    (
      targetText.includes("1127") ||
      targetText.includes("STUDIO")
    )
  ) {
    return (
      candidateText.includes("STYLING") &&
      (
        candidateText.includes("1127") ||
        candidateText.includes("STUDIO")
      )
    );
  }

  // PBB JV 2 Summarecon
  if (
    targetText.includes("PBB") &&
    targetText.includes("JV") &&
    targetText.includes("2")
  ) {
    return (
      candidateText.includes("PBB") &&
      candidateText.includes("JV") &&
      candidateText.includes("2")
    );
  }

  // Dropbox
  if (targetText.includes("DROPBOX")) {
    return candidateText.includes("DROPBOX");
  }

  // Complimentary March
  if (
    targetText.includes("COMPLIMENTARY") &&
    targetText.includes("MARET")
  ) {
    return (
      candidateText.includes("COMPLIMENTARY") &&
      candidateText.includes("MARET")
    );
  }

  // Buka puasa
  if (
    targetText.includes("BUKA") &&
    targetText.includes("PUASA")
  ) {
    return (
      candidateText.includes("BUKA") &&
      candidateText.includes("PUASA")
    );
  }

  // Package meeting
  if (
    targetText.includes("PAKET") &&
    targetText.includes("MEETING")
  ) {
    return (
      candidateText.includes("PAKET") &&
      candidateText.includes("MEETING")
    );
  }

  // Open table
  if (
    targetText.includes("OPEN") &&
    targetText.includes("TABLE")
  ) {
    return (
      candidateText.includes("OPEN") &&
      candidateText.includes("TABLE")
    );
  }

  // Talenta
  if (targetText.includes("TALENTA")) {
    return candidateText.includes("TALENTA");
  }

  return null;
}

function latestDate(rows) {
  const dates = rows
    .map(row => row.date)
    .filter(Boolean)
    .sort();

  return dates.length ? dates[dates.length - 1] : null;
}

function determineStatus(amount, realizationAmount) {
  const balance = amount - realizationAmount;

  if (Math.abs(balance) <= 1) {
    return "SETTLED";
  }

  if (balance > 0) {
    return "PARTIAL";
  }

  return "OVER_SETTLED";
}

const usedGL = new Set();
const workingPaperResult = [];
const matchDetail = [];

for (const wp of workingPaper) {
  const wpDescription = wp.description ?? "";
  const wpReferences = extractReferences(wpDescription);

  let candidates = [];
  let matchMethod = "NO_MATCH";
  let confidence = 0;

  /*
   * 1. Exact PO/WO matching
   */
  if (wpReferences.length) {
    candidates = glCredits.filter(gl => {
      if (usedGL.has(gl.glRowId)) {
        return false;
      }

      const glReferences = extractReferences(gl.description);

      return wpReferences.some(reference => {
        return glReferences.includes(reference);
      });
    });

    if (candidates.length) {
      matchMethod = "PO_WO_EXACT";
      confidence = 1;
    }
  }

  /*
   * 2. Phrase matching untuk item tanpa PO/WO
   */
  if (!candidates.length) {
    const scoredCandidates = glCredits
      .filter(gl => !usedGL.has(gl.glRowId))
      .map(gl => {
        const ruleResult = phraseRule(
          wpDescription,
          gl.description
        );

        const similarity = similarityScore(
          wpDescription,
          gl.description
        );

        return {
          gl,
          ruleResult,
          score: similarity.score,
          matchedTokens: similarity.matchedTokens
        };
      })
      .filter(item => {
        if (item.ruleResult === false) {
          return false;
        }

        if (item.ruleResult === true) {
          return item.score >= 0.15;
        }

        return item.score >= 0.45;
      });

    if (scoredCandidates.length) {
      const bestScore = Math.max(
        ...scoredCandidates.map(item => item.score)
      );

      const hasExplicitRule = scoredCandidates.some(item => {
        return item.ruleResult === true;
      });

      if (hasExplicitRule) {
        candidates = scoredCandidates.map(item => item.gl);
      } else {
        candidates = scoredCandidates
          .filter(item => {
            return item.score >= Math.max(
              0.45,
              bestScore - 0.15
            );
          })
          .map(item => item.gl);
      }

      if (candidates.length) {
        matchMethod = hasExplicitRule
          ? "PHRASE_RULE"
          : "PHRASE_SIMILARITY";

        confidence = Number(
          bestScore.toFixed(2)
        );
      }
    }
  }

  const realizationAmount = candidates.reduce(
    (total, gl) => total + Number(gl.credit || 0),
    0
  );

  const balance = Number(wp.amount || 0) - realizationAmount;

  const status = candidates.length
    ? determineStatus(wp.amount, realizationAmount)
    : "UNSETTLED";

  for (const gl of candidates) {
    usedGL.add(gl.glRowId);

    matchDetail.push({
      wpRowId: wp.wpRowId,
      wpVoucherNo: wp.voucherNo,
      wpDescription: wp.description,

      glRowId: gl.glRowId,
      glDate: gl.date,
      glJournalNo: gl.journalNo,
      glDescription: gl.description,
      glCredit: gl.credit,

      matchMethod,
      confidence
    });
  }

  workingPaperResult.push({
    ...wp,

    realizationDate: candidates.length
      ? latestDate(candidates)
      : null,

    realizationVouchers: candidates
      .map(gl => gl.journalNo)
      .filter(Boolean),

    realizationAmount,

    balance,

    status,
    matchMethod,
    confidence
  });
}

const unmatchedGL = glCredits
  .filter(gl => !usedGL.has(gl.glRowId))
  .map(gl => ({
    ...gl,
    status: "UNMATCHED_GL"
  }));

const totalAdvance = workingPaperResult.reduce(
  (total, row) => total + Number(row.amount || 0),
  0
);

const totalRealization = workingPaperResult.reduce(
  (total, row) => total + Number(row.realizationAmount || 0),
  0
);

const totalBalance = workingPaperResult.reduce(
  (total, row) => total + Number(row.balance || 0),
  0
);

const positiveOutstanding = workingPaperResult.reduce(
  (total, row) => {
    return total + Math.max(Number(row.balance || 0), 0);
  },
  0
);

const summary = {
  period: "April 2026",
  totalAdvance,
  totalRealization,
  totalBalance,
  positiveOutstanding,

  workingPaperCount: workingPaperResult.length,
  matchedWorkingPaperCount: workingPaperResult.filter(row => {
    return row.realizationAmount > 0;
  }).length,

  settledCount: workingPaperResult.filter(row => {
    return row.status === "SETTLED";
  }).length,

  partialCount: workingPaperResult.filter(row => {
    return row.status === "PARTIAL";
  }).length,

  overSettledCount: workingPaperResult.filter(row => {
    return row.status === "OVER_SETTLED";
  }).length,

  unsettledCount: workingPaperResult.filter(row => {
    return row.status === "UNSETTLED";
  }).length,

  glCreditCount: glCredits.length,
  matchedGLCount: matchDetail.length,
  unmatchedGLCount: unmatchedGL.length,

  outstandingItems: workingPaperResult
    .filter(row => {
      return row.balance > 0;
    })
    .map(row => ({
      wpRowId: row.wpRowId,
      description: row.description,
      amount: row.amount,
      realizationAmount: row.realizationAmount,
      balance: row.balance,
      status: row.status
    }))
};

return [
  {
    json: {
      runId: new Date().toISOString(),
      period: "2026-04",

      summary,
      workingPaperResult,
      matchDetail,
      unmatchedGL
    }
  }
];

const data = $('Match').first().json;

return data.workingPaperResult.map(row => ({
  json: {
    runId: data.runId,
    wpRowId: row.wpRowId,
    advanceDate: row.advanceDate,
    voucherNo: row.voucherNo,
    description: row.description,
    amount: row.amount,
    realizationDate: row.realizationDate,
    realizationVouchers: (row.realizationVouchers || []).join(', '),
    realizationAmount: row.realizationAmount,
    balance: row.balance,
    status: row.status,
    matchMethod: row.matchMethod ?? '',
    confidence: row.confidence ?? ''
  }
}));

const data = $('Match').first().json;

return (data.matchDetail || []).map(row => ({
  json: {
    runId: data.runId,
    wpRowId: row.wpRowId,
    wpVoucherNo: row.wpVoucherNo,
    wpDescription: row.wpDescription,
    glRowId: row.glRowId,
    glDate: row.glDate,
    glJournalNo: row.glJournalNo,
    glDescription: row.glDescription,
    glCredit: row.glCredit,
    matchMethod: row.matchMethod,
    confidence: row.confidence
  }
}));

const data = $('Match').first().json;

return (data.unmatchedGL || []).map(row => ({
  json: {
    runId: data.runId,
    glRowId: row.glRowId,
    sourceRowIndex: row.sourceRowIndex,
    date: row.date,
    journalNo: row.journalNo,
    description: row.description,
    debit: row.debit,
    credit: row.credit,
    status: 'UNMATCHED'
  }
}));

const data = $('Match').first().json;
const summary = data.summary;

const outstandingItems = (data.workingPaperResult || [])
  .filter(row => Number(row.balance) > 0)
  .map(row => ({
    voucherNo: row.voucherNo,
    description: row.description,
    originalAmount: row.amount,
    realizationAmount: row.realizationAmount,
    balance: row.balance,
    status: row.status
  }));

const overSettledItems = (data.workingPaperResult || [])
  .filter(row => row.status === 'OVER_SETTLED')
  .map(row => ({
    voucherNo: row.voucherNo,
    description: row.description,
    originalAmount: row.amount,
    realizationAmount: row.realizationAmount,
    balance: row.balance
  }));

return [
  {
    json: {
      runId: data.runId,

      summaryPayload: {
        period: 'April 2026',
        totalAdvance: summary.totalAdvance,
        totalRealization: summary.totalRealization,
        positiveOutstanding: summary.positiveOutstanding,
        settledCount: summary.settledCount,
        partialCount: summary.partialCount,
        overSettledCount: summary.overSettledCount,
        unmatchedGLCount: summary.unmatchedGLCount,
        outstandingItems,
        overSettledItems
      },

      dashboardBase: {
        runId: data.runId,
        period: 'April 2026',
        totalAdvance: summary.totalAdvance,
        totalRealization: summary.totalRealization,
        positiveOutstanding: summary.positiveOutstanding,
        settledCount: summary.settledCount,
        partialCount: summary.partialCount,
        overSettledCount: summary.overSettledCount,
        unmatchedGLCount: summary.unmatchedGLCount,
        outstandingItems: JSON.stringify(outstandingItems),
        overSettledItems: JSON.stringify(overSettledItems)
      }
    }
  }
];

const source = $('Build - AI Summary Payload').first().json;
const ai = $('DeepSeek - Executive Summary').first().json;

function parseList(value) {
  if (Array.isArray(value)) return value;

  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  }

  return [];
}

function rupiah(value) {
  return `Rp ${Number(value || 0).toLocaleString('id-ID')}`;
}

function formatOutstanding(value) {
  const items = parseList(value);

  if (!items.length) {
    return 'Tidak ada outstanding.';
  }

  return items.map((item, index) => {
    return `${index + 1}. ${item.voucherNo || '-'} | ${item.description || '-'} | Realisasi: ${rupiah(item.realizationAmount)} | Saldo: ${rupiah(item.balance)} | Status: ${item.status || '-'}`;
  }).join('\n');
}

function formatOverSettled(value) {
  const items = parseList(value);

  if (!items.length) {
    return 'Tidak ada over-settled.';
  }

  return items.map((item, index) => {
    const originalAmount = Number(
      item.originalAmount ?? item.amount ?? 0
    );

    const realizationAmount = Number(
      item.realizationAmount ?? 0
    );

    const overSettlement = Math.max(
      0,
      realizationAmount - originalAmount
    );

    return [
      `${index + 1}. ${item.voucherNo || '-'}`,
      item.description || '-',
      `Realisasi: ${rupiah(realizationAmount)}`,
      `Lebih bayar: ${rupiah(overSettlement)}`
    ].join(' | ');
  }).join('\n');
}

let response = ai;

if (typeof response === 'string') {
  try {
    response = JSON.parse(response);
  } catch {}
}

if (typeof response.body === 'string') {
  try {
    response.body = JSON.parse(response.body);
  } catch {}
}

if (typeof response.data === 'string') {
  try {
    response.data = JSON.parse(response.data);
  } catch {}
}

const apiResponse =
  response.body ||
  response.data ||
  response;

const executiveSummary =
  apiResponse.choices?.[0]?.message?.content?.trim() ||
  'DeepSeek mengembalikan content kosong.';

return [
  {
    json: {
      ...source.dashboardBase,

      period: '2026-04',

      executiveSummary,

      outstandingItems: formatOutstanding(
        source.dashboardBase.outstandingItems
      ),

      overSettledItems: formatOverSettled(
        source.dashboardBase.overSettledItems
      ),

      generatedAt: new Date().toISOString()
    }
  }
];

const payload =
  $('Build - AI Summary Payload').first().json.summaryPayload;

return [
  {
    json: {
      model: 'deepseek-flash',

      messages: [
        {
          role: 'system',
          content:
            'Anda adalah analis Finance. Buat executive summary singkat dalam Bahasa Indonesia. Jangan mengubah atau mengarang angka. Sebutkan total advance, total realisasi, saldo outstanding, item yang masih memiliki saldo, dan saran tindak lanjut.'
        },
        {
          role: 'user',
          content:
            'Data settlement April 2026:\n' +
            JSON.stringify(payload)
        }
      ],

      // Penting: matikan thinking agar jawaban masuk ke content
      thinking: {
        type: 'disabled'
      },

      temperature: 0.2,
      max_tokens: 800,
      stream: false
    }
  }
];
